6	/*
7	 * sdpdock_inject_hg_option — 在内层 IP 头中注入 HG Option
8	 *
9	 * 根据魔数选择注入模式:
10	 *   GA_MARK_MAGIC        → SNAT forward (flags=0, len=12), 写入 src_branch_id
11	 *   ZTNA_CVPN_MARK_MAGIC → BRANCH_DEST (flags=0x04, len=16), 写入 src/dst_branch_id
12	 *
13	 * dst_branch_id 按 BranchID 编码方案构造:
14	 *   (BRANCH_TYPE_ZTNA_CONNECTORVPN << 24) | (0 << 16) | target_pop_id
15	 *
16	 * 驱动模式下替代 TC eBPF 程序 ga_tun_mark.c：
17	 * 数据包通过 udp_tunnel_xmit_skb 直接发出不再经过 wgmeshd,
18	 * 但接收端 wgmeshd 仍需 HG Option 来确定路由决策,
19	 * 因此在内核模块中完成注入。
20	 */
21	void sdpdock_inject_hg_option(struct sdpdock *sd, struct sk_buff *skb, u16 magic,
22	                              u16 target_pop_id, u32 src_branch_id)
23	{
24	    struct iphdr *iph = (struct iphdr *)skb->data;
25	    unsigned int orig_tot_len;
26	    u8 opt_len, flags;
27	    u8 *opt;
28	
29	    if (iph->version != 4 || iph->ihl != 5) {
30	        SDPDOCK_STAT_INC(sd, tx_hg_skip_invalid);
31	        return;
32	    }
33	    if (skb->len < sizeof(*iph)) {
34	        SDPDOCK_STAT_INC(sd, tx_hg_skip_invalid);
35	        return;
36	    }
37	
38	    orig_tot_len = ntohs(iph->tot_len);
39	    if (orig_tot_len < sizeof(struct iphdr)) {
40	        SDPDOCK_STAT_INC(sd, tx_hg_skip_invalid);
41	        return;
42	    }
43	    if (skb->len < orig_tot_len) {
44	        SDPDOCK_STAT_INC(sd, tx_hg_skip_invalid);
45	        return;
46	    }
47	
48	    /* 根据魔数确定 HG Option 长度和 flags。
49	     *
50	     * 前置条件: 调用方 (dispatch.c) 保证 magic 只可能是 GA_MARK_MAGIC
51	     * 或 ZTNA_CVPN_MARK_MAGIC。WARN_ON_ONCE 捕获违反前置条件的调用。 */
52	    WARN_ON_ONCE(magic != GA_MARK_MAGIC && magic != ZTNA_CVPN_MARK_MAGIC);
53	    opt_len = hg_opt_len(magic);
54	    if (opt_len != HG_OPT_LEN && opt_len != HG_OPT_LEN_BRANCH) {
55	        SDPDOCK_STAT_INC(sd, tx_hg_skip_invalid);
56	        return;
57	    }
58	    if (magic == ZTNA_CVPN_MARK_MAGIC) {
59	        flags = HG_FLAG_BRANCH_DEST; /* 0x04 */
60	    } else {
61	        flags = 0;                   /* SNAT forward */
62	    }
63	
64	    /* 扩展 skb head: 在 data 前腾出 opt_len 字节,
65	     * 然后 memmove 将原始 20 字节 IP 头移到新位置 */
66	    skb_push(skb, opt_len);
67	    memmove(skb->data, skb->data + opt_len, sizeof(*iph));
68	
69	    /* 写入 HG Option (紧接 IP 头之后) */
70	    opt = skb->data + sizeof(*iph);
71	    opt[0] = HG_OPT_TYPE;
72	    opt[1] = opt_len;
73	    opt[2] = flags;
74	    opt[3] = 0;  /* reserved */
75	    *(__be16 *)&opt[4] = htons(target_pop_id);
76	    *(__be16 *)&opt[6] = 0;  /* entry_pop_id = 0 (wgmeshd 填充) */
77	    *(__be32 *)&opt[8] = htonl(src_branch_id);
78	
79	    if (magic == ZTNA_CVPN_MARK_MAGIC) {
80	        u32 dst_branch_id = (BRANCH_TYPE_ZTNA_CONNECTORVPN << BRANCH_TYPE_SHIFT) |
81	                            (0 << BRANCH_SEQ_SHIFT) |
82	                            target_pop_id;
83	        *(__be32 *)&opt[12] = htonl(dst_branch_id);
84	    }
85	
86	    /* 修正 IP 头: ihl 5→(5 + opt_len/4), tot_len, checksum */
87	    struct iphdr *new_iph = (struct iphdr *)skb->data;
88	    new_iph->ihl = 5 + opt_len / 4;
89	    new_iph->tot_len = htons(orig_tot_len + opt_len);
90	    ip_send_check(new_iph);
91	
92	    SDPDOCK_STAT_INC(sd, tx_hg_injected);
93	    if (magic == ZTNA_CVPN_MARK_MAGIC)
94	        SDPDOCK_STAT_INC(sd, tx_hg_ztna_cvpn);
95	    else
96	        SDPDOCK_STAT_INC(sd, tx_hg_ga);
97	}
