1	// SPDX-License-Identifier: GPL-2.0
2	// GA TUN mark: inject HG IP Option based on skb->mark
3	// Attached to TUN egress in tenant netns by sdpdock
4	//go:build ignore
5	
6	#include <bpf/ctx/skb.h>     // TC context: __sk_buff, TC_ACT_OK, skb_adjust_room
7	#include <linux/byteorder.h>  // __LITTLE_ENDIAN_BITFIELD / __BIG_ENDIAN_BITFIELD (needed by linux/ip.h)
8	#include <linux/ip.h>         // struct iphdr
9	#include <bpf/loader.h>       // __uint, __type macros for map definitions
10	
11	// Endian helpers — same logic as cilium/lib/endian.h but without heavy bpf/api.h deps
12	#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
13	# define ga_htons(x)  __builtin_bswap16(x)
14	# define ga_ntohs(x)  __builtin_bswap16(x)
15	#else
16	# define ga_htons(x)  (x)
17	# define ga_ntohs(x)  (x)
18	#endif
19	
20	#define SEC(NAME) __section(NAME)
21	
22	#define HG_OPT_TYPE   0x9F
23	#define HG_OPT_LEN    12
24	#define GA_MARK_MAGIC 0x4741  // 'G','A' ASCII
25	
26	struct {
27		__uint(type, BPF_MAP_TYPE_ARRAY);
28		__uint(max_entries, 1);
29		__type(key, __u32);
30		__type(value, __u64);
31	} pkt_cnt SEC(".maps");
32	
33	SEC("tc")
34	int ga_inject_hg_option(struct __sk_buff *skb)
35	{
36		// Count every packet that reaches TC egress (before any early return)
37		__u32 zero = 0;
38		__u64 *cnt = map_lookup_elem(&pkt_cnt, &zero);
39		if (cnt)
40			__sync_fetch_and_add(cnt, 1);
41	
42		// mark[31:16] = magic, mark[15:0] = target_pop_id; validate both in one read
43		__u32 mark = skb->mark;
44		if ((mark >> 16) != GA_MARK_MAGIC || (mark & 0xFFFF) == 0)
45			return TC_ACT_OK;
46		__u16 target_pop_id = mark & 0xFFFF;
47	
48		// TUN is L3 — no ethernet header, data starts at IP header
49		void *data = (void *)(long)skb->data;
50		void *data_end = (void *)(long)skb->data_end;
51		struct iphdr *iph = data;
52		if ((void *)(iph + 1) > data_end)
53			return TC_ACT_OK;
54		if (iph->version != 4 || iph->ihl != 5)
55			return TC_ACT_OK;
56	
57		// Build the complete 32-byte header in a stack buffer BEFORE skb_adjust_room.
58		// BPF_ADJ_ROOM_NET on TUN (mac_len=0) prepends HG_OPT_LEN bytes at data[0],
59		// shifting the original IP header to data[HG_OPT_LEN]. We must write the
60		// full modified 32-byte header (20B IP + 12B HG option) after adjustment.
61		__u8 new_hdr[32];
62		struct iphdr *new_iph = (struct iphdr *)new_hdr;
63	
64		// Copy original 20-byte IP header into stack buffer via struct fields
65		__builtin_memcpy(new_hdr, iph, 20);
66		new_iph->ihl   = 8;    // 5 → 8 (adds 12 bytes of options)
67		new_iph->tot_len = ga_htons(ga_ntohs(iph->tot_len) + HG_OPT_LEN);
68		new_iph->check = 0;    // zeroed for recomputation
69	
70		// Write HG Option at bytes 20–31 (type, len, flags, reserved, target_pop_id,
71		// entry_pop_id, branch_id — latter two filled by wgmeshd fast/slow path)
72		new_hdr[20] = HG_OPT_TYPE;
73		new_hdr[21] = HG_OPT_LEN;
74		new_hdr[22] = 0;  // flags = forward
75		new_hdr[23] = 0;  // reserved
76		*(__be16 *)&new_hdr[24] = ga_htons(target_pop_id);  // target_pop_id
77		*(__be16 *)&new_hdr[26] = 0;  // entry_pop_id = 0 (wgmeshd fills)
78		*(__be32 *)&new_hdr[28] = 0;  // branch_id = 0 (wgmeshd fills)
79	
80		// Compute IP checksum over 32-byte header (16 x __be16), fully unrolled
81		__u32 csum = 0;
82		__be16 *p = (__be16 *)new_hdr;
83		#pragma unroll
84		for (int i = 0; i < 16; i++)
85			csum += p[i];
86		csum = (csum & 0xFFFF) + (csum >> 16);
87		csum = (csum & 0xFFFF) + (csum >> 16);
88		new_iph->check = (__sum16)~csum;
89	
90		// Prepend HG_OPT_LEN bytes at the start of the L3 packet
91		if (skb_adjust_room(skb, HG_OPT_LEN, BPF_ADJ_ROOM_NET, 0) < 0)
92			return TC_ACT_OK;
93	
94		// Re-fetch pointers; data[0..31] is now available for our 32-byte header
95		data = (void *)(long)skb->data;
96		data_end = (void *)(long)skb->data_end;
97		if ((__u8 *)data + 32 > (__u8 *)data_end)
98			return TC_ACT_OK;
99	
100		// Write the complete 32-byte header (modified IP + HG option) into the packet
101		__builtin_memcpy(data, new_hdr, 32);
102	
103		return TC_ACT_OK;
104	}
