9	static void sdpdock_xmit_one(struct sdpdock_cpu_ctx *ctx, struct sk_buff *skb)
10	{
11	    struct sdpdock_skb_cb *cb = SDPDOCK_SKB_CB(skb);
12	    struct sdpdock_branch *branch = cb->branch;
13	    struct sdpdock *sd = cb->sd;
14	    bool need_hg;
15	    u16 target_pop_id;
16	    int nhead = branch->tx_spa_hdr_len + sizeof(struct udphdr) +
17	                sizeof(struct iphdr) + LL_MAX_HEADER;
18	    struct rtable *rt;
19	    struct socket *sock;
20	    struct flowi4 fl4;
21	    u32 inner_len;
22	    int pool_idx;
23	
24	    ctx->dequeue_count++;
25	
26	    if (!branch || !sd) {
27	        sdpdock_branch_put(branch);
28	        dev_kfree_skb(skb);
29	        return;
30	    }
31	
32	    u32 mark = skb->mark;
33	    u16 magic = mark >> 16;
34	    target_pop_id = mark & 0xFFFF;
35	    need_hg = ((magic == GA_MARK_MAGIC || magic == ZTNA_CVPN_MARK_MAGIC) &&
36	               target_pop_id != 0);
37	
38	    if (need_hg)
39	        nhead += hg_opt_len(magic);
40	
41	    if (skb_cow_head(skb, nhead)) {
42	        dev_kfree_skb(skb);
43	        SDPDOCK_STAT_INC(branch, tx_errors);
44	        sdpdock_branch_put(branch);
45	        return;
46	    }
47	
48	    if (need_hg)
49	        sdpdock_inject_hg_option(sd, skb, magic, target_pop_id, branch->branch_id);
50	
51	    skb_push(skb, branch->tx_spa_hdr_len);
52	    memcpy(skb->data, branch->tx_spa_hdr, branch->tx_spa_hdr_len);
53	
54	    if (unlikely(sd->sock_pool.count == 0)) {
55	        dev_kfree_skb(skb);
56	        SDPDOCK_STAT_INC(branch, tx_errors);
57	        sdpdock_branch_put(branch);
58	        return;
59	    }
60	
61	    pool_idx = cb->rss % sd->sock_pool.count;
62	
63	    sock = sd->sock_pool.socks[pool_idx];
64	
65	    /* 路由查找 */
66	    fl4 = (struct flowi4){
67	        .daddr = sd->remote_ip,
68	        .saddr = inet_sk(sock->sk)->inet_saddr,
69	        .flowi4_proto = IPPROTO_UDP,
70	        .fl4_sport = sd->sock_pool.ports[pool_idx],
71	        .fl4_dport = sd->remote_port,
72	    };
73	
74	    rt = ip_route_output_key(sd->owner_net, &fl4);
75	    if (IS_ERR(rt)) {
76	        pr_warn_ratelimited("sdpdock: route to %pI4 failed err=%ld\n",
77	            &sd->remote_ip, PTR_ERR(rt));
78	        dev_kfree_skb(skb);
79	        SDPDOCK_STAT_INC(branch, tx_route_err);
80	        sdpdock_branch_put(branch);
81	        return;
82	    }
83	
84	    if (fl4.saddr == 0) {
85	        ip_rt_put(rt);
86	        dev_kfree_skb(skb);
87	        SDPDOCK_STAT_INC(branch, tx_route_err);
88	        sdpdock_branch_put(branch);
89	        return;
90	    }
91	
92	    /* 发送: udp_tunnel_xmit_skb 接管 skb 所有权 */
93	    inner_len = skb->len - branch->tx_spa_hdr_len;
94	    udp_tunnel_xmit_skb(rt, sock->sk, skb,
95	        fl4.saddr,                     /* 源 IP */
96	        sd->remote_ip,                 /* 目标 IP */
97	        0,                             /* TOS */
98	        ip4_dst_hoplimit(&rt->dst),    /* TTL */
99	        0,                             /* DF */
100	        sd->sock_pool.ports[pool_idx], /* 源端口 */
101	        sd->remote_port,               /* 目标端口 */
102	        false,                         /* xnet */
103	        true);                         /* nocheck - 跳过 UDP checksum */
104	
105	    u64_stats_update_begin(&branch->stats.syncp);
106	    u64_stats_inc(&branch->stats.tx_packets);
107	    u64_stats_add(&branch->stats.tx_bytes, inner_len);
108	    u64_stats_update_end(&branch->stats.syncp);
109	    sdpdock_branch_put(branch);
110	}
