112	static int sdpdock_xmit_thread(void *data)
113	{
114	    struct sdpdock_cpu_ctx *ctx = data;
115	    struct sk_buff_head local_queue;
116	    struct sk_buff *skb;
117	
118	    skb_queue_head_init(&local_queue);
119	
120	    while (!kthread_should_stop()) {
121	        wait_event_interruptible(ctx->wq,
122	            !skb_queue_empty(&ctx->queue) || kthread_should_stop());
123	
124	        if (kthread_should_stop() && skb_queue_empty(&ctx->queue))
125	            break;
126	
127	        spin_lock_bh(&ctx->lock);
128	        skb_queue_splice_init(&ctx->queue, &local_queue);
129	        spin_unlock_bh(&ctx->lock);
130	
131	        /* 与 ndo_start_xmit (BH 上下文) 保持一致，防止 udp_tunnel_xmit_skb
132	         * 触发 softirq 重入 */
133	        local_bh_disable();
134	        while ((skb = __skb_dequeue(&local_queue)))
135	            sdpdock_xmit_one(ctx, skb);
136	        local_bh_enable();
137	    }
138	
139	    /* 清理线程退出时残留的数据包 (kthread_stop 前, active 已设为 0,
140	     * synchronize_rcu 已确保没有新的入队) */
141	    spin_lock_bh(&ctx->lock);
142	    while ((skb = __skb_dequeue(&ctx->queue))) {
143	        struct sdpdock_skb_cb *cb = SDPDOCK_SKB_CB(skb);
144	        if (cb->branch)
145	            sdpdock_branch_put(cb->branch);
146	        dev_kfree_skb(skb);
147	    }
148	    spin_unlock_bh(&ctx->lock);
149	
150	    return 0;
151	}
152	
153	int sdpdock_percpu_enqueue(struct sdpdock_branch *branch, struct sk_buff *skb)
154	{
155	    struct sdpdock *sd;
156	    struct sdpdock_cpu_ctx *ctx;
157	    struct sdpdock_skb_cb *cb;
158	    u32 rss;
159	    int idx, cpu;
160	
161	    if (!branch)
162	        return -ENODEV;
163	    if (!refcount_inc_not_zero(&branch->refcount))
164	        return -ENODEV;
165	    sd = branch->sd;
166	
167	    rcu_read_lock();
168	
169	    if (!atomic_read(&sd->dispatch.active) || sd->dispatch.num_cpus == 0) {
170	        rcu_read_unlock();
171	        SDPDOCK_STAT_INC(branch, tx_errors);
172	        sdpdock_branch_put(branch);
173	        return -ENODEV;
174	    }
175	
176	    rss = sdpdock_skb_rss(skb);
177	    idx = rss % sd->dispatch.num_cpus;
178	    cpu = sd->dispatch.cpu_ids[idx];
179	
180	    ctx = rcu_dereference(sd->dispatch.ctxs[cpu]);
181	    if (!ctx) {
182	        rcu_read_unlock();
183	        SDPDOCK_STAT_INC(branch, tx_errors);
184	        sdpdock_branch_put(branch);
185	        return -ENODEV;
186	    }
187	
188	    if (skb_queue_len(&ctx->queue) >= sd->dispatch.max_queue_len) {
189	        ctx->drop_count++;
190	        rcu_read_unlock();
191	        SDPDOCK_STAT_INC(branch, tx_errors);
192	        sdpdock_branch_put(branch);
193	        return -ENOSPC;
194	    }
195	
196	    cb = SDPDOCK_SKB_CB(skb);
197	    cb->branch = branch;
198	    cb->sd = sd;
199	    cb->rss = rss;
200	
201	    spin_lock_bh(&ctx->lock);
202	    __skb_queue_tail(&ctx->queue, skb);
203	    ctx->enqueue_count++;
204	    spin_unlock_bh(&ctx->lock);
205	
206	    wake_up(&ctx->wq);
207	    rcu_read_unlock();
208	    return 0;
209	}
210	
211	int sdpdock_dispatch_init(struct sdpdock *sd)
212	{
213	    int i, cpu, idx = 0;
214	
215	    sd->dispatch.num_cpus = 0;
216	    for_each_online_cpu(cpu) {
217	        struct sdpdock_cpu_ctx *ctx;
218	
219	        if (cpu >= MAX_CPUS) {
220	            pr_err("sdpdock: CPU %d exceeds MAX_CPUS\n", cpu);
221	            goto rollback;
222	        }
223	
224	        ctx = kzalloc(sizeof(*ctx), GFP_KERNEL);
225	        if (!ctx)
226	            goto rollback;
227	
228	        skb_queue_head_init(&ctx->queue);
229	        spin_lock_init(&ctx->lock);
230	        init_waitqueue_head(&ctx->wq);
231	        ctx->cpu = cpu;
232	
233	        ctx->thread = kthread_create(sdpdock_xmit_thread, ctx, "sdpdock_tx/%d", cpu);
234	        if (IS_ERR(ctx->thread)) {
235	            kfree(ctx);
236	            goto rollback;
237	        }
238	        kthread_bind(ctx->thread, cpu);
239	        wake_up_process(ctx->thread);
240	
241	        sd->dispatch.cpu_ids[idx] = cpu;
242	        rcu_assign_pointer(sd->dispatch.ctxs[cpu], ctx);
243	        idx++;
244	    }
245	    sd->dispatch.num_cpus = idx;
246	    sd->dispatch.max_queue_len = MAX_QUEUE_LEN;
247	    atomic_set(&sd->dispatch.active, 1);
248	    return 0;
249	
250	rollback:
251	    for (i = 0; i < idx; i++) {
252	        cpu = sd->dispatch.cpu_ids[i];
253	        struct sdpdock_cpu_ctx *ctx = rcu_dereference_protected(sd->dispatch.ctxs[cpu], true);
254	        if (ctx && ctx->thread)
255	            kthread_stop(ctx->thread);
256	        RCU_INIT_POINTER(sd->dispatch.ctxs[cpu], NULL);
257	        kfree(ctx);
258	    }
259	    return -ENOMEM;
260	}
261	
262	void sdpdock_dispatch_destroy(struct sdpdock *sd)
263	{
264	    int i, cpu;
265	
266	    atomic_set(&sd->dispatch.active, 0);
267	    synchronize_rcu();
268	
269	    /* 先并行唤醒所有线程让其退出 (参照 srtunnel_percpu_exit) */
270	    for (i = 0; i < sd->dispatch.num_cpus; i++) {
271	        cpu = sd->dispatch.cpu_ids[i];
272	        struct sdpdock_cpu_ctx *ctx = rcu_dereference_protected(sd->dispatch.ctxs[cpu], true);
273	        if (ctx)
274	            wake_up(&ctx->wq);
275	    }
276	
277	    /* 然后逐一停止并释放 */
278	    for (i = 0; i < sd->dispatch.num_cpus; i++) {
279	        cpu = sd->dispatch.cpu_ids[i];
280	        struct sdpdock_cpu_ctx *ctx = rcu_dereference_protected(sd->dispatch.ctxs[cpu], true);
281	        if (!ctx)
282	            continue;
283	
284	        if (ctx->thread)
285	            kthread_stop(ctx->thread);
286	
287	        RCU_INIT_POINTER(sd->dispatch.ctxs[cpu], NULL);
288	        kfree(ctx);
289	    }
290	}
