14	#include "spa_wire.h"  /* via ccflags-y += -I$(PWD)/../../sasebpf/sase */
15	
16	/* 模块配置常量 */
17	#define MAX_SOCKS               32
18	#define MAX_QUEUE_LEN           4096
19	#define MAX_CPUS                256
20	
21	/* 设备常量 */
22	#define SDPDOCK_MTU             1360
23	
24	/* HG (HyperGate) IP Option 协议常量 (与 hyper_gate/protocol/hg_option.h 对齐) */
25	#define HG_OPT_TYPE             0x9F  /* copied=1, class=0, number=31 */
26	#define HG_OPT_LEN              12    /* SNAT/GA 模式长度 */
27	#define HG_OPT_LEN_BRANCH       16    /* BRANCH_DEST 模式长度 (含 dst_branch_id) */
28	#define HG_FLAG_BRANCH_DEST     0x04  /* bit2: 分支目的模式 */
29	#define GA_MARK_MAGIC           0x4741  /* 'G','A' ASCII — GA-NAT, HG SNAT 模式 */
30	#define ZTNA_CVPN_MARK_MAGIC    0x5A54  /* 'Z','T' ASCII — ZTNA, HG BRANCH_DEST 模式, dst=connectorvpn */
