8	/* sdpdock_create_socket_pool: 创建 UDP socket 池 (含错误恢复) */
9	int sdpdock_create_socket_pool(struct sdpdock *sd, __be16 *ports, int count)
10	{
11	    int i, ret;
12	
13	    for (i = 0; i < count; i++) {
14	        struct udp_port_cfg udp_conf = {
15	            .family = AF_INET,
16	            .local_ip.s_addr = htonl(INADDR_ANY),
17	            .local_udp_port = ports[i],
18	            .use_udp_checksums = true,
19	        };
20	        struct socket *sock;
21	
22	        ret = udp_sock_create(sd->owner_net, &udp_conf, &sock);
23	        if (ret) {
24	            pr_err("sdpdock: failed to create UDP socket port %d: %d\n", ntohs(ports[i]), ret);
25	            sd->sock_pool.count = i;
26	            sdpdock_destroy_socket_pool(sd);
27	            return ret;
28	        }
29	        sd->sock_pool.socks[i] = sock;
30	        sd->sock_pool.ports[i] = ports[i];
31	
32	        /* 注册 UDP encap 回调 (与 srtunnel 使用独立 encap_type, 避免冲突) */
33	        struct udp_tunnel_sock_cfg encap_cfg = {
34	            .encap_type = SDPDOCK_UDP_ENCAP_TYPE,
35	            .encap_rcv = sdpdock_udp_recv,
36	        };
37	        setup_udp_tunnel_sock(sd->owner_net, sock, &encap_cfg);
38	    }
39	    sd->sock_pool.count = count;
40	    return 0;
41	}
