43	/* sdpdock_destroy_socket_pool: 先清除 encap 注册, 再 waiting RCU, 最后释放 socket */
44	void sdpdock_destroy_socket_pool(struct sdpdock *sd)
45	{
46	    int i;
47	    struct socket *socks_to_release[MAX_SOCKS] = {NULL};
48	    struct udp_tunnel_sock_cfg cfg = {
49	        .encap_type = 0,
50	        .encap_rcv = NULL,
51	        .sk_user_data = NULL,
52	    };
53	
54	    for (i = 0; i < sd->sock_pool.count; i++) {
55	        if (sd->sock_pool.socks[i]) {
56	            socks_to_release[i] = sd->sock_pool.socks[i];
57	            setup_udp_tunnel_sock(sd->owner_net, socks_to_release[i], &cfg);
58	            sd->sock_pool.socks[i] = NULL;
59	        }
60	    }
61	    synchronize_rcu();
62	
63	    for (i = 0; i < sd->sock_pool.count; i++) {
64	        if (socks_to_release[i]) {
65	            udp_tunnel_sock_release(socks_to_release[i]);
66	        }
67	    }
68	    sd->sock_pool.count = 0;
69	}
