71	/* UDP encap 接收回调 */
72	static int sdpdock_udp_recv(struct sock *sk, struct sk_buff *skb)
73	{
74	    struct sdpdock *sd = &sdpdock;
75	    struct spa_parse_result spa;
76	    struct sdpdock_branch *branch;
77	    struct net_device *dev;
78	
79	    if (skb_linearize(skb)) {
80	        SDPDOCK_STAT_INC(sd, rx_parse_err);
81	        goto drop;
82	    }
83	
84	    if (!skb_pull(skb, sizeof(struct udphdr))) {
85	        SDPDOCK_STAT_INC(sd, rx_parse_err);
86	        goto drop;
87	    }
88	
89	    if (spa_parse_header(skb->data, skb->len, &spa)) {
90	        SDPDOCK_STAT_INC(sd, rx_parse_err);
91	        goto drop;
92	    }
93	
94	    if (spa.version != SPA_VERSION) {
95	        SDPDOCK_STAT_INC(sd, rx_version_err);
96	        goto drop;
97	    }
98	    if (spa.dir != SPA_DIR_SC && spa.dir != SPA_DIR_FC) {
99	        SDPDOCK_STAT_INC(sd, rx_dir_err);
100	        goto drop;
101	    }
102	
103	    if (spa.next_proto != SPA_PROTO_NONE && spa.next_proto != SPA_PROTO_IPV4) {
104	        SDPDOCK_STAT_INC(sd, rx_proto_err);
105	        goto drop;
106	    }
107	
108	    /* 在全局哈希表中查找 VNI */
109	    branch = sdpdock_branch_lookup(sd, spa.vni);
110	    if (!branch) {
111	        SDPDOCK_STAT_INC(sd, rx_lookup_miss);
112	        goto drop;
113	    }
114	
115	    if (branch->branch_id != spa.branch_id) {
116	        SDPDOCK_STAT_INC(branch, rx_dropped);
117	        SDPDOCK_STAT_INC(sd, rx_branch_mismatch);
118	        sdpdock_branch_put(branch);
119	        goto drop;
120	    }
121	
122	    if (spa.next_proto == SPA_PROTO_NONE) {
123	        SDPDOCK_STAT_INC(sd, rx_hb_drop);
124	        sdpdock_branch_put(branch);
125	        goto drop;
126	    }
127	
128	    if (!skb_pull(skb, spa.hdr_total)) {
129	        SDPDOCK_STAT_INC(branch, rx_errors);
130	        sdpdock_branch_put(branch);
131	        goto drop;
132	    }
133	
134	    if (skb->len < sizeof(struct iphdr)) {
135	        SDPDOCK_STAT_INC(branch, rx_errors);
136	        sdpdock_branch_put(branch);
137	        goto drop;
138	    }
139	    struct iphdr *iph = (struct iphdr *)skb->data;
140	    if (iph->version != 4 || iph->ihl < 5) {
141	        SDPDOCK_STAT_INC(branch, rx_errors);
142	        sdpdock_branch_put(branch);
143	        goto drop;
144	    }
145	
146	    dev = READ_ONCE(branch->dev);
147	    if (!dev) {
148	        sdpdock_branch_put(branch);
149	        goto drop;
150	    }
151	    skb->dev = dev;
152	    skb_scrub_packet(skb, true);
153	    skb_reset_network_header(skb);
154	    skb_reset_transport_header(skb);
155	    skb->protocol = htons(ETH_P_IP);
156	
157	    /*
158	     * rx_bytes 在 netif_receive_skb 之前累加, 计入所有通过解析的有效包。
159	     * rx_packets 仅在 netif_receive_skb 成功后累加。
160	     */
161	    SDPDOCK_STAT_ADD(branch, rx_bytes, skb->len);
162	
163	    if (netif_receive_skb(skb) == NET_RX_DROP) {
164	        SDPDOCK_STAT_INC(branch, rx_dropped);
165	    } else {
166	        SDPDOCK_STAT_INC(branch, rx_packets);
167	    }
168	    sdpdock_branch_put(branch);
169	    return 0;
170	
171	drop:
172	    kfree_skb(skb);
173	    return 0;
174	}
